CREATE TABLE journey_legs(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,origin VARCHAR2(200) NOT NULL,destination VARCHAR2(200) NOT NULL,departure TIMESTAMP WITH TIME ZONE NOT NULL,arrival TIMESTAMP WITH TIME ZONE NOT NULL,timezone VARCHAR2(80) NOT NULL,transfer_details VARCHAR2(1000) NOT NULL,source VARCHAR2(500) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL,CHECK(arrival>departure));
CREATE INDEX journey_trip ON journey_legs(trip_id,departure);
